/**
 * §4.9 guest migration on a real v1 localStorage snapshot (generated by the
 * v1 quiz engine: scripts/progress/make-v1-fixture.ts), the shipped v2
 * dataset and the shipped legacy map.
 */
import { describe, expect, it } from "vitest";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { parseDatasetV2 } from "@/lib/openings";
import { modelOf, parseCourseId } from "@/lib/courses-client";
import type { RawDatasetV2 } from "@/lib/openings-build/dataset";
import type { LegacyMap } from "@/lib/openings-build/legacy";
import { cardKey, isReviewable, review, State, type CardState } from "@/lib/srs/fsrs";
import { reviewQueue } from "@/lib/trainer/plan";
import { findSystem, loadCourse } from "@/lib/courses-client";
import { MAX_INTERVAL_DAYS, datasetPlacer, migrateV1, rowMoveFor, sm2ToFsrs, sourceHash, type Placer, type V1Card } from "../migrate-v1";

const root = join(__dirname, "../../../..");
const raw = JSON.parse(readFileSync(join(root, "public/data/openings.v2.json"), "utf8")) as RawDatasetV2;
const ds = parseDatasetV2(raw, "test");
const model = modelOf(ds);
const legacy = JSON.parse(readFileSync(join(root, "public/data/legacy-map.v1.json"), "utf8")) as LegacyMap;
const fixture = JSON.parse(readFileSync(join(__dirname, "fixtures/v1-localStorage.json"), "utf8")) as { localStorage: Record<string, string> };
const snap = fixture.localStorage;
const v1Cards = Object.values(JSON.parse(snap["cot.v1.cards"])) as V1Card[];
const NOW = new Date("2026-10-18T12:00:00Z");
const placer = datasetPlacer(ds);
const empty = { cards: {}, courses: {} };
const out = migrateV1(snap, legacy, placer, empty, NOW);

const v1 = (o: Partial<V1Card>): V1Card => ({ openingId: 0, epd: "x w - -", lineSans: [], ease: 2.5, intervalDays: 6, reps: 2, lapses: 0, due: "2026-10-20T00:00:00.000Z", seen: 2, correct: 2, ...o });

describe("SM-2 → FSRS state (ADR 0003)", () => {
  it("difficulty is linear in ease: 2.5 → 5, 1.3 → 9, clamped to 1–10", () => {
    expect(sm2ToFsrs(v1({ ease: 2.5 }), "white", "e4").card.difficulty).toBeCloseTo(5);
    expect(sm2ToFsrs(v1({ ease: 1.3 }), "white", "e4").card.difficulty).toBeCloseTo(9);
    expect(sm2ToFsrs(v1({ ease: 3.0 }), "white", "e4").card.difficulty).toBeCloseTo(5 - 0.5 * (4 / 1.2));
    expect(sm2ToFsrs(v1({ ease: 4.5 }), "white", "e4").card.difficulty).toBe(1);
  });
  it("stability = max(0.5, interval); due, reps, lapses kept; last review = due − interval", () => {
    const { card } = sm2ToFsrs(v1({ intervalDays: 6, reps: 2, lapses: 1 }), "white", "e4+");
    expect(card).toMatchObject({ stability: 6, reps: 2, lapses: 1, state: State.Review, due: "2026-10-20T00:00:00.000Z", answer: "e4", migratedFrom: "sm2" });
    expect(card.last_review).toBe("2026-10-14T00:00:00.000Z");
    expect(sm2ToFsrs(v1({ intervalDays: 0.1 }), "white", "e4").card.stability).toBe(0.5);
  });
  it("a lapsed card (reps 0, seen) is Relearning, due as v1 had it", () => {
    const { card } = sm2ToFsrs(v1({ intervalDays: 0, reps: 0, lapses: 2, seen: 3 }), "black", "c5");
    expect(card.state).toBe(State.Relearning);
    expect(card.due).toBe("2026-10-20T00:00:00.000Z");
    expect(card.last_review).toBe("2026-10-19T23:50:00.000Z");
  });
  it("runaway v1 intervals are clamped to the FSRS maximum, measured from the real last review", () => {
    const { card, clamped } = sm2ToFsrs(v1({ intervalDays: 2254732.2, due: "8199-07-15T22:53:40.000Z" }), "white", "e4");
    expect(clamped).toBe(true);
    expect(card.stability).toBe(MAX_INTERVAL_DAYS);
    expect(new Date(card.due).getTime() - new Date(card.last_review!).getTime()).toBe(MAX_INTERVAL_DAYS * 86400_000);
    // the fixture really contains such cards (v1 grew intervals on same-day repeats)
    expect(out.report.clamped).toBeGreaterThan(0);
  });
  it("migrated cards review normally with ts-fsrs", () => {
    for (const c of Object.values(out.cards)) {
      const next = review(c, "good", NOW);
      expect(Number.isFinite(next.stability)).toBe(true);
      expect(new Date(next.due).getTime()).toBeGreaterThan(NOW.getTime());
    }
  });
});

describe("cards on the real v1 fixture", () => {
  it("every card is placed (none dropped) and keyed (side to move, epd, answer)", () => {
    expect(out.report.v1Cards).toBe(v1Cards.length);
    expect(out.report.dropped).toEqual([]);
    for (const [key, c] of Object.entries(out.cards)) {
      expect(key).toBe(cardKey(c.side, c.epd, c.answer));
      expect(c.side).toBe(c.epd.split(" ")[1] === "w" ? "white" : "black");
      const node = model.byEpd.get(c.epd)!;
      expect(model.nodes[node].theoryByNorm.has(c.answer)).toBe(true);
    }
  });
  it("answer: the v1 row's own move where the card is on the row; else the course's book move", () => {
    // v1 cards don't record which theory move was played; the row's move is
    // known only when the card's line is a prefix of the row (the v1 quiz
    // walked the whole family, so most cards sit deeper than their row)
    let onRow = 0;
    for (const c of v1Cards) {
      const side = c.epd.split(" ")[1] === "w" ? "white" : "black";
      const row = rowMoveFor(c, legacy);
      const p = placer.place(c.epd, side, row, row ? legacy.entries[c.openingId].bestCourseId : null)!;
      if (row) {
        onRow++;
        expect(p.answer).toBe(row);
      } else if (p.courseId) {
        const id = parseCourseId(p.courseId)!;
        const course = loadCourse(ds, findSystem(ds, id.hub, id.system, id.side)!)!;
        const node = model.byEpd.get(c.epd)!;
        const l = course.lines.find((x) => x.nodes.indexOf(node) >= 0 && x.nodes.indexOf(node) < x.sans.length)!;
        expect(p.answer).toBe(l.sans[l.nodes.indexOf(node)].replace(/[+#]$/, ""));
      }
    }
    expect(onRow).toBeGreaterThan(10);
    const a = out.report.answers;
    expect(a.row + a.book + a.popular).toBe(v1Cards.length);
  });
  it("merge: several v1 cards on one v2 key keep the most reps (ties → earliest due) and sum lapses/seen/correct", () => {
    expect(out.report.merged).toBeGreaterThan(0);
    const groups = new Map<string, V1Card[]>();
    for (const c of v1Cards) {
      const side = c.epd.split(" ")[1] === "w" ? "white" : "black";
      const row = rowMoveFor(c, legacy);
      const p = placer.place(c.epd, side, row, row ? legacy.entries[c.openingId].bestCourseId : null)!;
      const k = cardKey(side, c.epd, p.answer);
      groups.set(k, [...(groups.get(k) ?? []), c]);
    }
    expect(Object.keys(out.cards).length).toBe(groups.size);
    for (const [k, g] of groups) {
      const m = out.cards[k];
      expect(m.lapses).toBe(g.reduce((s, c) => s + c.lapses, 0));
      expect(m.seen).toBe(g.reduce((s, c) => s + c.seen, 0));
      expect(m.correct).toBe(g.reduce((s, c) => s + c.correct, 0));
      const best = [...g].sort((a, b) => b.reps - a.reps || (a.due < b.due ? -1 : 1))[0];
      expect(m.reps).toBe(best.reps);
    }
  });
  it("each placed card is reviewable in the course it's filed under", () => {
    const due = Object.fromEntries(Object.entries(out.cards).map(([k, c]) => [k, { ...c, due: NOW.toISOString(), state: State.Review }])) as Record<string, CardState>;
    const byCourse = new Map<string, string[]>();
    for (const [k, c] of Object.entries(due)) if (c.lastCourseId) byCourse.set(c.lastCourseId, [...(byCourse.get(c.lastCourseId) ?? []), k]);
    expect(byCourse.size).toBeGreaterThan(0);
    for (const [id, keys] of byCourse) {
      const p = parseCourseId(id)!;
      const course = loadCourse(ds, findSystem(ds, p.hub, p.system, p.side)!)!;
      const sub = Object.fromEntries(keys.map((k) => [k, due[k]]));
      const queued = reviewQueue(model, course, sub, NOW).reduce((n, it) => n + it.plies.length, 0);
      expect(queued).toBe(keys.length);
      for (const k of keys) expect(isReviewable(due[k], NOW)).toBe(true);
    }
  });
  it("existing v2 cards win over migrated ones", () => {
    const [k, c] = Object.entries(out.cards)[0];
    const mine = { ...c, reps: 0, migratedFrom: undefined };
    const again = migrateV1(snap, legacy, placer, { cards: { [k]: mine }, courses: {} }, NOW);
    expect(again.cards[k]).toBeUndefined();
    expect(again.report.kept).toBe(1);
  });
  it("a position missing from the v2 tree is dropped and logged; never thrown", () => {
    const bad = { ...JSON.parse(snap["cot.v1.cards"]), "1|8/8/8/8/8/8/8/K6k w - -": v1({ openingId: 1, epd: "8/8/8/8/8/8/8/K6k w - -" }) };
    const r = migrateV1({ ...snap, "cot.v1.cards": JSON.stringify(bad) }, legacy, placer, empty, NOW);
    expect(r.report.dropped).toEqual([{ openingId: 1, epd: "8/8/8/8/8/8/8/K6k w - -", reason: "position not in the v2 tree" }]);
  });
});

describe("the rest of the guest data", () => {
  it("opening progress → course progress, keyed by the course the opening's cards landed in", () => {
    const ops = Object.values(JSON.parse(snap["cot.v1.openingProgress"])) as { openingId: number; seen: number; correct: number }[];
    expect(out.report.droppedCourses).toEqual([]);
    const total = Object.values(out.courseProgress).reduce((s, p) => s + p.v1!.seen, 0);
    expect(total).toBe(ops.reduce((s, o) => s + o.seen, 0));
    for (const p of Object.values(out.courseProgress)) {
      expect(parseCourseId(p.courseId)).not.toBeNull();
      expect(p.lines).toEqual({});
    }
    // Ruy Lopez (White) progress lands in a White Ruy Lopez course
    expect(Object.keys(out.courseProgress).some((id) => id.startsWith("ruy-lopez/") && id.endsWith("@white"))).toBe(true);
    // Najdorf (Black) in a Black Sicilian course
    expect(Object.keys(out.courseProgress).some((id) => id.startsWith("sicilian-defense/") && id.endsWith("@black"))).toBe(true);
  });
  it("v1 attempts become the activity log (streaks carry over)", () => {
    const attempts = JSON.parse(snap["cot.v1.attempts"]) as { correct: boolean; at: string }[];
    const days = Object.values(out.activity);
    expect(days.reduce((s, d) => s + d[0], 0)).toBe(attempts.length);
    expect(days.reduce((s, d) => s + d[1], 0)).toBe(attempts.filter((a) => a.correct).length);
    expect(Object.keys(out.activity).sort()).toEqual([...new Set(attempts.map((a) => a.at.slice(0, 10)))].sort());
  });
  it("attempts, profile and prefs pass through unchanged", () => {
    expect(out.attempts).toBe(snap["cot.v1.attempts"]);
    expect(out.profile).toBe(snap["cot.v1.profile"]);
    expect(out.prefs).toBe(snap["cot.v1.prefs"]);
  });
  it("the source hash is stable and changes with the data (idempotence marker)", () => {
    expect(sourceHash(snap)).toBe(sourceHash({ ...snap }));
    expect(sourceHash({ ...snap, "cot.v1.prefs": "{}" })).not.toBe(sourceHash(snap));
    expect(out.report.hash).toBe(sourceHash(snap));
  });
  it("placement order with a stub placer: rowMove first", () => {
    const seen: (string | null)[] = [];
    const stub: Placer = { place: (_e, _s, row) => (seen.push(row), { answer: row ?? "e4", courseId: null }) };
    migrateV1(snap, legacy, stub, empty, NOW);
    expect(seen.filter(Boolean).length).toBeGreaterThan(0);
  });
});
